#!/usr/bin/env bash
# Review finding 9 / 4B.9: airlock_ai.documents.extract_text converts Office files with the
# real headless LibreOffice through the real forensic_analyze parser sandbox (bwrap when it
# works here, as on the image). Inputs are generated by hand (stdlib zipfile, no python-docx):
# a minimal OOXML .docx and two-sheet .xlsx and .ods workbooks with neutral text.
#
# Checks: the text comes back; every sheet comes back in workbook order with its name; the
# source folder is left exactly as it was (read-only bind: no LibreOffice lock file, no change);
# the work folder holds no LibreOffice profile or output afterwards.
set -euo pipefail
# shellcheck source=tests/functional/lib.sh
source "$(dirname "${BASH_SOURCE[0]}")/lib.sh"
require_cmd python3
command -v soffice >/dev/null 2>&1 || command -v libreoffice >/dev/null 2>&1 ||
  skip "LibreOffice (soffice) is not installed here; the image installs it (tools_ai)"

src="$TEST_TMP/src"
work="$TEST_TMP/work"
# The sandbox drops to the parse user when run as root: it must reach the inputs.
chmod 755 "$TEST_TMP"
python3 "$REPO_ROOT/tests/fixtures/ai/make-document-fixtures.py" "$src"
chmod 755 "$src"
chmod 644 "$src"/*
before="$(cd "$src" && find . -mindepth 1 -printf '%P\n' | sort && sha256sum -- * | sort)"

run python3 - "$src" "$work" <<'PY'
import json
import sys
from pathlib import Path

from airlock_ai import documents
from airlock_ai.tools import sandbox_runner
from forensic_analyze import sandbox

src, work = Path(sys.argv[1]), Path(sys.argv[2])
info = sandbox.Sandbox().describe()
run_tool = sandbox_runner(work)
out = {"sandbox": info}
for name in ("note.docx", "sheets.xlsx", "sheets.ods"):
    doc = documents.extract_text(src / name, run_tool, work / name)
    out[name] = {"text": doc.text, "method": doc.method, "error": doc.error}
print(json.dumps(out))
PY
assert_eq "$RC" "0" "extract_text: $OUT"
json="$(tail -n 1 <<<"$OUT")"
field() { python3 -c 'import json,sys; d=json.loads(sys.argv[1]); print(eval(sys.argv[2], {}, {"d": d}))' "$json" "$1"; }

method="$(field 'd["sandbox"]["method"]')"
echo "sandbox method: $method (user $(field 'd["sandbox"]["user"]'), network $(field 'd["sandbox"]["network"]'))"
if [[ "$(id -u)" -eq 0 ]] && command -v bwrap >/dev/null 2>&1 &&
  bwrap --unshare-net --ro-bind / / -- /bin/true >/dev/null 2>&1; then
  assert_eq "$method" "bwrap" "bwrap works here, so the sandbox must use it"
fi
if [[ "$method" != "none" ]]; then
  assert_eq "$(field 'd["sandbox"]["network"]')" "none" "the converter has no network"
fi

for name in note.docx sheets.xlsx sheets.ods; do
  assert_eq "$(field "d['$name']['error']")" "" "$name converted"
done
assert_contains "$(field 'd["note.docx"]["text"]')" \
  "The meeting about office chairs moved to Tuesday." "docx text"
for name in sheets.xlsx sheets.ods; do
  assert_eq "$(field "d['$name']['method']")" "soffice csv (2 sheets)" "$name: every sheet"
  text="$(field "d['$name']['text']")"
  assert_contains "$text" "=== Sheet 1: Zeta ===" "$name first sheet"
  assert_contains "$text" "=== Sheet 2: Alpha ===" "$name second sheet"
  assert_contains "$text" "chairs,four" "$name first sheet text"
  assert_contains "$text" "tables," "$name second sheet text"
  zeta="${text%%=== Sheet 1: Zeta ===*}"
  alpha="${text%%=== Sheet 2: Alpha ===*}"
  ((${#zeta} < ${#alpha})) || fail "$name: sheets out of workbook order"
done

after="$(cd "$src" && find . -mindepth 1 -printf '%P\n' | sort && sha256sum -- * | sort)"
assert_eq "$after" "$before" "the source folder is unchanged (no lock file, no write)"
leftover="$(find "$work" \( -name 'soffice-profile' -o -name 'soffice-out' \) -print)"
assert_eq "$leftover" "" "LibreOffice profile and output removed"
pass "documents extracted in the $method sandbox"
